import{_ as t,o as r,c as a,a0 as s}from"./chunks/framework.DScjKhBS.js";const h=JSON.parse('{"title":"EDI Repository Portfolio Analysis","description":"Senior-engineer review of 57 Elixirr/iOLAP git repositories — AI enablement, academy, DSO, MSDP, client delivery, and WordPress transfer guidance.","frontmatter":{"layout":"doc","title":"EDI Repository Portfolio Analysis","description":"Senior-engineer review of 57 Elixirr/iOLAP git repositories — AI enablement, academy, DSO, MSDP, client delivery, and WordPress transfer guidance."},"headers":[],"relativePath":"reports/edi-repos-analysis/index.md","filePath":"reports/edi-repos-analysis/index.md"}'),i={name:"reports/edi-repos-analysis/index.md"};function o(n,e,d,l,p,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="edi-repository-portfolio-analysis" tabindex="-1">EDI Repository Portfolio Analysis <a class="header-anchor" href="#edi-repository-portfolio-analysis" aria-label="Permalink to &quot;EDI Repository Portfolio Analysis&quot;">​</a></h1><p>Senior-engineer review of <strong>57 git repositories</strong> under the Elixirr/iOLAP internal portfolio: AI enablement boilerplates, academy training material, DSO tooling, MSDP data platform infrastructure, client delivery artifacts, and QA patterns.</p><p><strong>Prepared:</strong> 2026-06-08 · <strong>Scope:</strong> <code>/Users/rosstweedie/Sites/edi</code></p><hr><h2 id="key-findings" tabindex="-1">Key findings <a class="header-anchor" href="#key-findings" aria-label="Permalink to &quot;Key findings&quot;">​</a></h2><ul><li>No substantive PHP or WordPress application code exists in this portfolio</li><li>The only WordPress touchpoint is Cypress selectors against a demo page in <code>qa-cypress</code></li><li>Several clones are empty or stub-only (README on <code>main</code>, real code on unfetched branches)</li><li>Highest-value repos for engineering standards adoption are the AI enablement boilerplates and secure SDLC agent pack</li><li>Cross-cutting weakness: tests and CI lag behind documentation across most repos</li></ul><p><strong>Recommended priority for PHP/WordPress teams:</strong></p><ol><li><a href="./reports/edi-repos-analysis/03-ai-enablement-boilerplates.html#apps-cursor-ai-enablement"><code>apps-cursor-ai-enablement</code></a> — AI-assisted delivery workflow reference</li><li><a href="./reports/edi-repos-analysis/04-secure-sdlc-governance.html#elixirr-secure-sdlc-agent-pack"><code>elixirr-secure-sdlc-agent-pack</code></a> — security governance (includes PHP globs)</li><li><a href="./reports/edi-repos-analysis/03-ai-enablement-boilerplates.html#apps-ai-enablement-fastapi"><code>apps-ai-enablement-fastapi</code></a> — module architecture pattern</li><li><a href="./reports/edi-repos-analysis/03-ai-enablement-boilerplates.html#apps-ai-enablement-netapi"><code>apps-ai-enablement-netAPI</code></a> — boundary testing and CI enforcement</li><li><a href="./reports/edi-repos-analysis/09-qa-testing.html#qa-cursor-ai-enablement"><code>qa-cursor-ai-enablement</code></a> — modern testing standards</li><li><a href="./reports/edi-repos-analysis/09-qa-testing.html#pull-request-validation"><code>pull-request-validation</code></a> — PR gate pattern</li></ol><hr><h2 id="report-sections" tabindex="-1">Report sections <a class="header-anchor" href="#report-sections" aria-label="Permalink to &quot;Report sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><a href="./reports/edi-repos-analysis/01-executive-summary.html">1. Executive summary</a></td><td>Key findings and priority repos</td></tr><tr><td><a href="./reports/edi-repos-analysis/02-portfolio-overview.html">2. Portfolio overview</a></td><td>Category counts, patterns, weaknesses, attention list</td></tr><tr><td><a href="./reports/edi-repos-analysis/03-ai-enablement-boilerplates.html">3. AI enablement boilerplates</a></td><td>11 Cursor and stack template repos</td></tr><tr><td><a href="./reports/edi-repos-analysis/04-secure-sdlc-governance.html">4. Secure SDLC and governance</a></td><td>SSDLC agent pack, Cloud Buddy, AI plan repos</td></tr><tr><td><a href="./reports/edi-repos-analysis/05-academy-lms.html">5. Academy and LMS</a></td><td>12 training and course repositories</td></tr><tr><td><a href="./reports/edi-repos-analysis/06-dso-internal-tooling.html">6. DSO internal tooling</a></td><td>Docker builds, scans, interview vault</td></tr><tr><td><a href="./reports/edi-repos-analysis/07-msdp-data-platform.html">7. MSDP data platform</a></td><td>CloudFormation, dbt, Redshift, pipelines</td></tr><tr><td><a href="./reports/edi-repos-analysis/08-client-delivery-production.html">8. Client delivery and production</a></td><td>Endeavor, ms-shared, ML lab, iolap-kb</td></tr><tr><td><a href="./reports/edi-repos-analysis/09-qa-testing.html">9. QA and testing</a></td><td>QA enablement, Cypress, PR validation</td></tr><tr><td><a href="./reports/edi-repos-analysis/10-frontend-and-infra.html">10. Front-end and infrastructure</a></td><td>CRA boilerplate, OpenAPI mock, CDK snippets</td></tr><tr><td><a href="./reports/edi-repos-analysis/11-patterns-and-maturity.html">11. Patterns and maturity</a></td><td>Style summary and maturity matrix</td></tr><tr><td><a href="./reports/edi-repos-analysis/12-wp-recommendations.html">12. WordPress recommendations</a></td><td>Adoption plan, leadership tiers, bottom line</td></tr></tbody></table><p>Start with the <a href="./reports/edi-repos-analysis/01-executive-summary.html">executive summary</a>.</p><hr><h2 id="bottom-line" tabindex="-1">Bottom line <a class="header-anchor" href="#bottom-line" aria-label="Permalink to &quot;Bottom line&quot;">​</a></h2><p>This portfolio is an <strong>AI enablement and cloud training ecosystem</strong>, not a WordPress codebase. The gap between these repos and typical WP delivery is <strong>standardization</strong>: Cursor rules as coding standards, architecture boundary enforcement, and CI as a non-negotiable merge gate. Those three practices transfer directly without requiring a stack change.</p><p>Source: <code>edi-repos-analysis.md</code> (Dark Factory formatting pass, 2026-06-08).</p>',16)])])}const y=t(i,[["render",o]]);export{h as __pageData,y as default};
